package hu.synostream.android;
import android.content.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import org.json.*;import java.util.*;import java.io.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
@RunWith(AndroidJUnit4.class) public class Android0516Test {
 final Android050FlowTest f=new Android050FlowTest();File cache;byte[] original;static final String OLD="/Movies/Demo.Movie.2020.mkv",FRESH="/Movies/Fresh.Movie.2020.mkv";
 @Before public void init(){f.instrumentation=InstrumentationRegistry.getInstrumentation();f.context=f.instrumentation.getTargetContext();f.app=(SynoApp)f.context.getApplicationContext();f.device=UiDevice.getInstance(f.instrumentation);UiLocale.save(f.context,"hu");}
 @After public void cleanup()throws Exception{f.instrumentation.runOnMainSync(()->{f.app.cancelScan();f.app.libraryFactory=Library::new;f.app.connectionDraft.close();f.app.epoch++;});f.cleanup();UiLocale.save(f.context,"hu");}
 void waitFor(java.util.function.BooleanSupplier condition)throws Exception{long end=android.os.SystemClock.elapsedRealtime()+20000;while(!condition.getAsBoolean()&&android.os.SystemClock.elapsedRealtime()<end)Thread.sleep(50);assertTrue("Operation did not finish",condition.getAsBoolean());}
 void setup(FakeNas n)throws Exception{f.instrumentation.runOnMainSync(()->{f.app.client=null;f.app.recovery.reset();f.app.checkNetwork();});n.files.keySet().removeIf(p->p.startsWith("/Movies/")&&!p.equals(OLD));Library.Card old=new Library.Card(OLD,"Cached Hungarian title",true);old.id=1;old.origin="name";old.lookupState="matched";old.overview="Cached description";old.modified=100;f.setup(n,List.of(old));cache=f.app.cacheFile(f.app.selected());original=new JSONArray().put(old.json()).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);try(FileOutputStream out=new FileOutputStream(cache)){out.write(original);}}
 void fresh(FakeNas n){n.files.put(FRESH,new byte[]{0,1,2,3});n.times.put(FRESH,200L);}
 void scan(){f.instrumentation.runOnMainSync(()->f.app.scan(f.app.selected()));}
 void done()throws Exception{f.instrumentation.waitForIdleSync();waitFor(()->!f.app.busy&&!f.app.scanRunning);f.instrumentation.waitForIdleSync();}
 void cancel(){f.instrumentation.runOnMainSync(()->f.app.cancelScan());}
 JSONObject info(long id,String title)throws Exception{return new JSONObject().put("id",id).put("title",title).put("original_title",title).put("release_date","2020-01-01").put("overview","Fixture description");}
 Recognition.Api api(AtomicInteger searches,CountDownLatch entered,CountDownLatch release){return (endpoint,p)->{if(endpoint.startsWith("search/")){searches.incrementAndGet();if(entered!=null){entered.countDown();assertTrue(release.await(15,TimeUnit.SECONDS));}long id=p.get("query").startsWith("Fresh")?2:1;return new JSONObject().put("results",new JSONArray().put(info(id,p.get("query"))));}if(endpoint.endsWith("alternative_titles"))return new JSONObject();long id=Long.parseLong(endpoint.substring(endpoint.lastIndexOf('/')+1));return info(id,id==2?"Új műsor":"Régi műsor");};}
 @Test public void all235TasksAreShownAndLatestDownloadIsVisible()throws Exception{try(FakeNas n=new FakeNas()){setup(n);n.taskCount=235;n.taskPageTotal=true;f.click("menu_button");f.text("Letöltések");assertTrue(f.device.wait(Until.hasObject(By.text("235 feladat")),15000));assertTrue(f.device.wait(Until.hasObject(By.text("Latest active torrent")),5000));assertTrue(n.taskRequests>=4);assertEquals(0,n.starts);assertEquals(0,n.prepares);}}
 @Test public void newCardIsVisibleBeforeMetadataFinishesAndItsDataArrivesIncrementally()throws Exception{try(FakeNas n=new FakeNas()){setup(n);fresh(n);CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);AtomicInteger searches=new AtomicInteger();f.instrumentation.runOnMainSync(()->f.app.libraryFactory=(client,key,c)->new Library(client,api(searches,entered,release)));try{scan();assertTrue(entered.await(10,TimeUnit.SECONDS));assertTrue(f.device.wait(Until.hasObject(By.desc("Fresh Movie")),5000));assertTrue(f.app.scanRunning);assertTrue(f.device.hasObject(By.desc("Cached Hungarian title")));assertArrayEquals(original,java.nio.file.Files.readAllBytes(cache.toPath()));release.countDown();done();assertTrue(f.device.wait(Until.hasObject(By.desc("Új műsor")),5000));assertEquals(2,searches.get());assertEquals(2,f.app.rawCards.size());assertEquals(2,new JSONArray(new String(java.nio.file.Files.readAllBytes(cache.toPath()),java.nio.charset.StandardCharsets.UTF_8)).length());}finally{release.countDown();}}}
 void rollbackScenario(boolean cancel)throws Exception{try(FakeNas n=new FakeNas()){setup(n);fresh(n);n.folders.add("/Movies/Slow");n.gatedFolder="/Movies/Slow";try{scan();assertTrue(n.folderEntered.await(10,TimeUnit.SECONDS));assertTrue(f.device.wait(Until.hasObject(By.desc("Fresh Movie")),5000));assertTrue(f.app.scanRunning);if(cancel){f.device.executeShellCommand("pm grant "+f.pkg+" android.permission.POST_NOTIFICATIONS");AtomicReference<Intent> view=new AtomicReference<>();android.app.Instrumentation.ActivityMonitor monitor=new android.app.Instrumentation.ActivityMonitor(){@Override public android.app.Instrumentation.ActivityResult onStartActivity(Intent intent){if(Intent.ACTION_VIEW.equals(intent.getAction())){view.set(intent);return new android.app.Instrumentation.ActivityResult(android.app.Activity.RESULT_CANCELED,null);}return null;}};f.instrumentation.addMonitor(monitor);try{MainActivity a=f.activity();f.instrumentation.runOnMainSync(()->a.play(FRESH,false));waitFor(()->view.get()!=null);assertEquals(1,n.releaseFolder.getCount());}finally{f.instrumentation.removeMonitor(monitor);}cancel();}else n.failedFolder=n.gatedFolder;n.releaseFolder.countDown();done();assertEquals(1,f.app.rawCards.size());assertEquals(OLD,f.app.rawCards.get(0).path);assertEquals("Cached Hungarian title",f.app.rawCards.get(0).title);assertArrayEquals(original,java.nio.file.Files.readAllBytes(cache.toPath()));Thread.sleep(300);assertFalse(f.app.rawCards.stream().anyMatch(c->c.path.equals(FRESH)));}finally{n.releaseFolder.countDown();}}}
 @Test public void cancelRestoresCommittedListAndVideoCanStartDuringSlowFolderRead()throws Exception{rollbackScenario(true);}
 @Test public void failedInventoryRestoresCommittedListAndCache()throws Exception{rollbackScenario(false);}
 @Test public void normalRefreshReusesMatchesAndFullRefreshExplicitlyQueriesThem()throws Exception{try(FakeNas n=new FakeNas()){setup(n);fresh(n);AtomicInteger searches=new AtomicInteger(),forced=new AtomicInteger();f.instrumentation.runOnMainSync(()->f.app.libraryFactory=(client,key,cache)->{if(cache==null)forced.incrementAndGet();return new Library(client,api(searches,null,null));});scan();done();assertEquals(2,searches.get());scan();done();assertEquals(2,searches.get());f.device.findObject(By.desc(f.activity().getString(R.string.msg_more_options_dc34bb))).click();assertTrue(f.device.wait(Until.hasObject(By.text("Összes médiaadat frissítése")),5000));f.text("Összes médiaadat frissítése");waitFor(()->forced.get()==1);done();assertEquals(1,forced.get());assertEquals(6,searches.get());}}
 @Test public void pendingSharedWritesDoNotDelayFirstAppearanceOfNewContent()throws Exception{try(FakeNas n=new FakeNas()){setup(n);fresh(n);n.holdUpload=true;f.instrumentation.runOnMainSync(()->{try{f.app.edits.manual(true,OLD,new JSONObject().put("id",77).put("title","Pinned fixture"));}catch(Exception e){throw new RuntimeException(e);}});try{scan();assertTrue(n.uploadEntered.await(10,TimeUnit.SECONDS));assertTrue(f.device.wait(Until.hasObject(By.desc("Fresh Movie")),5000));assertEquals(0,n.uploads);assertTrue(f.app.scanRunning);n.releaseUpload.countDown();done();assertEquals(1,n.uploads);assertEquals(77,f.app.rawCards.stream().filter(c->c.path.equals(OLD)).findFirst().get().id);}finally{n.releaseUpload.countDown();}}}
}
